const nav = useNavigate();
const auth = useAuth();
const store = useStore<{ checked: boolean }>({ checked: false });

// eslint-disable-next-line qwik/no-use-visible-task
useVisibleTask$(({ track }) => {
  const loading = track(() => auth.value.loading);

  if (loading) return;

  const brief = loadProjectBrief();
  if (brief) {
    // Returning writer: send them to the desk. Leave `checked` false so the
    // calm wordmark stays up through the redirect instead of flashing the
    // landing page.
    window.location.replace("/editor/");
    return;
  }
  store.checked = true;
});

