158	            <p
159	              class="mt-2 text-[11px] tracking-[0.18em] uppercase text-[var(--color-ink-muted)]"
160	              style="font-family: var(--font-typewriter);"
161	            >
162	              It may have been unpublished, or the handle may have changed.
163	            </p>
164	            <p class="mt-4">
165	              <Link
166	                href="/"
167	                class="text-[11px] tracking-[0.18em] uppercase text-[var(--color-vermilion)] hover:underline"
168	                style="font-family: var(--font-typewriter);"
169	              >
170	                Back to Twyne
171	              </Link>
172	            </p>
173	          </div>
174	        )}
175	
176	        {piece.value && (
177	          <article>
178	            <p
179	              class="text-[10px] tracking-[0.2em] uppercase text-[var(--color-ink-muted)]"
180	              style="font-family: var(--font-typewriter);"
