56	export async function loadBlogPieceBySlug(
57	  slug: string,
58	): Promise<PublishedPieceLoaderData> {
59	  const client = publishedClient();
60	  if (!client) return { piece: null, status: "unavailable" };
61	
62	  try {
63	    const listBlog = (api.published as unknown as {
64	      listBlog: unknown;
65	    }).listBlog;
66	    const all = (await (
67	      client.query as unknown as (
68	        ref: unknown,
69	        args: { limit?: number },
70	      ) => Promise<Array<{ slug: string }>>
71	    )(listBlog, { limit: 200 }));
72	    if (!all.some((piece) => piece.slug === slug)) {
73	      return { piece: null, status: "loaded" };
74	    }
75	
76	    const piece = await client.query(api.published.getBySlug, { slug });
77	    return { piece, status: "loaded" };
78	  } catch {
79	    return { piece: null, status: "unavailable" };
