100	function htmlToText(html: string): string {
101	  return html
102	    .replace(/<script[\s\S]*?<\/script>/gi, " ")
103	    .replace(/<style[\s\S]*?<\/style>/gi, " ")
104	    .replace(/<[^>]+>/g, " ")
105	    .replace(/&nbsp;/gi, " ")
106	    .replace(/&amp;/gi, "&")
107	    .replace(/&lt;/gi, "<")
108	    .replace(/&gt;/gi, ">")
109	    .replace(/&quot;/gi, '"')
110	    .replace(/&#39;/g, "'")
111	    .replace(/\s+/g, " ");
112	}
