114	function truncateMeta(input: string): string {
115	  const normalized = input.replace(/\s+/g, " ").trim();
116	  if (normalized.length <= 180) return normalized;
117	  return `${normalized.slice(0, 177).replace(/\s+\S*$/, "")}...`;
