12	export const RouterHead = component$(() => {
13	  const head = useDocumentHead();
14	  const loc = useLocation();
15	
16	  const origin = loc.url.origin || SITE;
17	  const ogImage = `${origin}/og-image.png`;
18	  const pageUrl = loc.url.href;
19	
20	  // Keys (name or property) a route already declared — render site-wide
21	  // social defaults only when the route hasn't overridden them.
22	  const declared = new Set(
23	    head.meta.map((m) => m.property ?? m.name).filter(Boolean) as string[],
24	  );
25	
26	  const title = head.title || "Twyne — An Editorial Room for Writers";
27	  const description =
28	    (head.meta.find((m) => m.name === "description")?.content as string) ??
29	    "Twyne is a writer-first editing room. Start from an interview, then draft with a brief, editorial personas, rubric review, and citation detection.";
30	
31	  const socialDefaults: Array<{
32	    property?: string;
33	    name?: string;
34	    content: string;
35	  }> = [
36	    { property: "og:type", content: "website" },
37	    { property: "og:site_name", content: "Twyne" },
38	    { property: "og:title", content: title },
39	    { property: "og:description", content: description },
40	    { property: "og:url", content: pageUrl },
